"""Build the full Frisco service directory and dedicated expanded-service pages."""
from pathlib import Path
from html import escape
import json,re
R=Path(__file__).resolve().parents[1]
D=json.loads((R/'assets/pool-expanded-services.json').read_text());by={x['slug']:x for x in D}
base=(R/'frisco-pool-service/index.html').read_text();header=base[base.index('<body>')+6:base.index('<main')];footer=base[base.index('<footer'):base.index('</body>')]
old={d['slug']:d for f in ['pool-services-content.json','pool-cleaning-content.json'] for d in json.loads((R/'assets'/f).read_text())}
N={k:x['name'] for k,x in old.items()};N.update({k:x['name'] for k,x in by.items()})
CATALOG=[('weekly-service','Weekly Pool Service','Maintenance'),('acid-wash-service','Pool Acid Washing','Specialized'),('pool-tile-cleaning','Pool Tile Calcium Removal','Specialized'),('pool-leak-detection-repair','Pool Leak Detection & Repair','Repairs'),('pool-pump-repair','Pool Pump Repair','Repairs'),('pool-filter-repair','Pool Filter Repair','Repairs'),('pool-heater-repair','Pool Heater Repair','Repairs'),('pool-automation','Pool Automation & Smart Controls','Upgrades'),('saltwater-pool-conversion','Saltwater Pool Conversion','Upgrades'),('pool-remodeling','Pool Remodeling','Remodeling'),('pool-pre-purchase-inspection','Pool Pre-Purchase Inspection','Specialized'),('pool-repair','Pool Equipment Repair','Repairs'),('pool-heating-cooling','Pool Heating & Cooling','Upgrades'),('pool-deck-coping-joint-repair','Pool Deck & Coping Joint Repair','Remodeling'),('pool-equipment-warranty-service','Pool Equipment Warranty Service','Specialized'),('pool-plumbing-repair','Pool Plumbing Repair','Repairs'),('pool-electrical-repair','Pool Electrical Repair','Repairs'),('pool-resurfacing','Pool Resurfacing','Remodeling'),('pool-tile-replacement','Pool Tile Replacement','Remodeling'),('pool-chiller-cooling-systems','Pool Chiller & Cooling Systems','Upgrades'),('pool-removal-backyard-restoration','Pool Removal & Backyard Restoration','Remodeling')]
extra={
'weekly-service':('Routine cleaning, water testing, baskets, and equipment observations, with specialty tasks clearly scoped.','/assets/pool-photos/pool-23.webp','Backyard swimming pool and patio'),
'acid-wash-service':('Assess persistent surface staining, finish suitability, treatment options, and professionally planned water handling.','/assets/pool-photos/pool-10.webp','Finished backyard pool and raised spa'),
'pool-tile-cleaning':('Assess waterline deposits and choose an appropriate cleaning method for sound tile, grout, and nearby finishes.','/assets/pool-photos/pool-16.webp','Pool waterline tile before and after cleaning'),
'pool-leak-detection-repair':('Investigate changing water levels, wet areas, fittings, equipment, and suspected concealed plumbing leaks.','/assets/pool-photos/pool-24.webp','Listening equipment used during a pool assessment'),
'pool-remodeling':('Coordinate finish, tile, coping, equipment, and desired backyard changes around the pool’s actual condition.','/assets/pool-photos/pool-00.webp','Backyard pool seen from above'),
'pool-repair':('Start with the symptom, then assess pumps, filters, controls, valves, and other installed equipment.','/assets/pool-photos/pool-07.webp','Technician assessing pool equipment'),
'pool-heating-cooling':('Compare repair and comfort-system options around the pool, equipment, temperature goals, and installation.','/assets/pool-photos/pool-26.webp','Pool heater at an outdoor equipment installation')}
def link(slug,label=None):return '<a href="/'+slug+'/">'+escape(label or N.get(slug,slug))+'</a>'
def head(title,desc,route,image,schemas):
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'+f'<title>{escape(title)}</title><meta name="description" content="{escape(desc,quote=True)}"><link rel="canonical" href="{route}"><meta name="theme-color" content="#123f53"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:image" content="{image}"><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@600;700&family=Poppins:wght@400;500;600;700&display=swap" rel="stylesheet">'+''.join(f'<link rel="stylesheet" href="/assets/{f}">' for f in ['pool-base.css','navigation.css','pool-services.css','frisco-local.css','pool-catalog.css','typography.css'])+'<link rel="icon" href="/assets/frisco-pool-icon.svg" type="image/svg+xml">'+''.join('<script type="application/ld+json">'+json.dumps(x,ensure_ascii=False).replace('</','<\\/')+'</script>' for x in schemas)+'</head><body>'+header

def hero(title,lead,image,alt,cta='#questions'):
 return f'<div class="local-hero"><div><span class="eyebrow">FRISCO POOL SERVICES · FRISCO, TEXAS</span><h1>{escape(title)}</h1><p>{escape(lead)}</p><div class="local-actions"><a class="btn" href="tel:+19457773345">Call 945-777-3345</a><a class="btn gold" href="{cta}">Explore service details</a></div></div><figure><img src="{image}" alt="{escape(alt,quote=True)}" width="1200" height="900" fetchpriority="high"><figcaption>Pool and equipment imagery illustrates the service topic.</figcaption></figure></div>'
def cta():return '<section class="final-cta"><span class="eyebrow">YOUR FRISCO BACKYARD</span><h2>Tell us what changed.<br>Let’s plan the next step.</h2><p>Share your address, equipment details, and the concern you want assessed.<br>Confirm availability, the work included, and pricing directly.</p><a class="btn" href="tel:+19457773345">Call 945-777-3345</a></section>'
for d in D:
 route='/'+d['slug']+'/';title=d['name']+' in Frisco'
 service={'@context':'https://schema.org','@type':'Service','name':title,'serviceType':d['name'],'description':d['description'],'url':route,'image':d['image'],'areaServed':{'@type':'City','name':'Frisco','containedInPlace':{'@type':'State','name':'Texas'}},'provider':{'@type':'Organization','name':'Frisco Pool Services','url':'/','telephone':'+1-945-777-3345','logo':'/assets/frisco-pool-logo.svg'}}
 faq={'@context':'https://schema.org','@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in d['questions']]}
 crumbs={'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':'/'},{'@type':'ListItem','position':2,'name':'Pool services','item':'/services/'},{'@type':'ListItem','position':3,'name':d['name'],'item':route}]}
 s=head(title+' | Frisco Pool Services',d['description'],route,d['image'],[service,faq,crumbs])+'<nav class="local-breadcrumb" aria-label="Breadcrumb"><a href="/">Home</a><span aria-hidden="true">/</span><a href="/services/">Pool services</a><span aria-current="page">'+escape(d['name'])+'</span></nav><main id="main">'
 s+=hero(title,d['lead'],d['image'],d['alt'])
 s+='<section class="local-section" id="scope"><span class="eyebrow">DEFINE THE WORK BEFORE THE VISIT</span><h2>What can this service cover?</h2><div class="local-grid">'+''.join('<article class="local-card"><h3>'+escape(h)+'</h3><p>'+escape(p)+'</p></article>' for h,p in d['scope'])+'</div></section>'
 s+='<section class="local-section local-layout" id="questions"><div>'
 for i,(q,a) in enumerate(d['questions'],1):s+=f'<article class="local-answer" id="question-{i}"><h2>{escape(q)}</h2><p>{escape(a)}</p></article>'
 s+='</div><aside class="local-toc"><span class="eyebrow">YOUR QUESTIONS, FIRST</span><h2>Find your next step</h2><nav aria-label="Service questions">'+''.join(f'<a href="#question-{i}">{escape(q)}</a>' for i,(q,a) in enumerate(d['questions'],1))+'</nav><a class="btn" href="#prepare">Prepare for the conversation</a></aside></section>'
 s+='<section class="local-section" id="prepare"><span class="eyebrow">MAKE THE REQUEST USEFUL</span><h2>What should I have ready?</h2><div class="local-brief"><div><h3>Details for your service request</h3><ul>'+''.join('<li>'+escape(x)+'</li>' for x in d['prepare'])+'</ul><p>Include the Frisco property address and any access constraints. Keep gate codes, account passwords, and personal records out of public photo reports.</p></div><div><h3>How is the work agreed?</h3><p>Describe the concern, then confirm the assessment or project scope, pricing, and appointment availability. Ask which parts, preparation, follow-up, and related repairs are included, and how additional work is approved. A phone inquiry does not itself book a visit.</p><a class="btn" href="tel:+19457773345">Discuss '+escape(d['name'].lower())+'</a></div></div>'
 refs={
 'pool-filter-repair':('https://www.pentair.com/pool-spa/education-support/homeowner-support/pool-filter-product-safety-help-center.html','Pentair’s filter safety and product support'),
 'pool-equipment-warranty-service':('https://www.pentair.com/en-us/warranty.html','Example manufacturer resource: Pentair warranty information'),
 'pool-electrical-repair':('https://www.friscotexas.gov/1521/Contractor-Registration-Information','City of Frisco contractor-registration information'),
 'pool-removal-backyard-restoration':('https://www.friscotexas.gov/211/Pools-Pool-Enclosures','City of Frisco pool and enclosure information'),
 'pool-resurfacing':('https://www.friscotexas.gov/525/Residents','City of Frisco stormwater and pool-maintenance guidance')}
 if d['slug'] in refs:
  u,label=refs[d['slug']];s+='<p class="local-reference">Useful reference: <a href="'+u+'">'+escape(label)+'</a>. Use the requirements and instructions applicable to your equipment, property, and proposed work.</p>'
 s+='</section><section class="local-section"><span class="eyebrow">RELATED WORK, CLEARLY SCOPED</span><h2>Could another service help?</h2><div class="local-service-links">'+''.join(link(x) for x in d['related'])+'</div><div class="local-bridge"><h3>Explore the full service range</h3><p>Compare '+link('services','all 21 pool services')+' or use the '+link('frisco-neighborhoods','Frisco neighborhood and county guides')+' for local planning questions. Cleaning and equipment work can have different scopes, even when they address the same symptom.</p></div></section>'+cta()+'</main>'+footer+'</body></html>'
 out=R/d['slug']/'index.html';out.parent.mkdir(exist_ok=True);out.write_text(s)
# Full primary catalogue, with each supplied service represented once and linked correctly.
items=[]
for number,(slug,name,cat) in enumerate(CATALOG,1):
 d=by.get(slug)
 desc,image,alt=(d.get('catalog_description',d['description']),d['image'],d['alt']) if d else extra[slug]
 items.append(dict(number=number,slug=slug,name=name,category=cat,description=desc,image=image,alt=alt))
(R/'assets/pool-service-catalog.json').write_text(json.dumps(items,indent=2,ensure_ascii=False)+'\n')
route='/services/';desc='Explore 21 pool services in Frisco: cleaning, repairs, automation, salt conversion, inspections, warranty inquiries, resurfacing, cooling, and removal.'
schema={'@context':'https://schema.org','@type':'CollectionPage','name':'Pool services in Frisco','url':route,'mainEntity':{'@type':'ItemList','numberOfItems':len(items),'itemListElement':[{'@type':'ListItem','position':x['number'],'name':x['name'],'url':'/'+x['slug']+'/'} for x in items]}}
s=head('Pool Services in Frisco | Cleaning, Repair & Remodeling',desc,route,'/assets/pool-photos/pool-23.webp',[schema])+'<main id="main">'+hero('Pool services in Frisco.','Explore 21 services for your Frisco pool—from the weekly routine and a noisy pump to smarter controls, a renewed finish, or a different future for the backyard.','/assets/pool-photos/pool-23.webp','Backyard swimming pool with a waterfall and a dog beside the water','#catalog')
s+='<section class="local-section" id="catalog"><span class="eyebrow">THE COMPLETE FRISCO SERVICE RANGE</span><h2>What does your pool need?</h2><p>Search a service or choose a category. Each guide explains the work, common questions, and what to discuss before booking.</p><div class="local-filters"><label for="catalogSearch">Search pool services<input id="catalogSearch" type="search" placeholder="Try pump, salt, tile, or inspection"></label><label for="catalogCategory">Service category<select id="catalogCategory"><option value="all">All services</option>'+''.join('<option>'+x+'</option>' for x in ['Maintenance','Repairs','Upgrades','Remodeling','Specialized'])+'</select></label><button class="btn gold" id="catalogReset" type="button">Clear filters</button></div><p id="catalogCount" role="status" aria-live="polite" class="local-count">21 of 21 services shown</p><div class="catalog-grid">'
for x in items:
 s+='<article class="catalog-card" data-service-card data-category="'+x['category']+'" data-search="'+escape(x['name']+' '+x['description'],quote=True)+'"><img src="'+x['image']+'" alt="'+escape(x['alt'],quote=True)+'" width="900" height="650" loading="lazy"><div class="catalog-copy"><span class="eyebrow">'+f'{x["number"]:02d}'+' · '+x['category']+'</span><h3>'+escape(x['name'])+'</h3><p>'+escape(x['description'])+'</p>'+link(x['slug'],'Explore '+x['name'].lower())+'</div></article>'
s+='</div><p id="catalogEmpty" hidden>No services match. Clear the filters or call with the problem you are seeing.</p><noscript><p>Filters require JavaScript. All 21 service links remain available above.</p></noscript></section><section class="local-section" id="cleaning"><span class="eyebrow">GO DEEPER INTO POOL CLEANING</span><h2>Need a more specific cleaning plan?</h2><p>Use these additional guides to distinguish an initial cleanup, recurring care, filter attention, and salt-system maintenance.</p><div class="local-service-links">'+''.join(link(x) for x in ['pool-cleaning','green-pool-cleaning','pool-filter-cleaning','saltwater-pool-maintenance','one-time-pool-cleaning'])+'</div></section><section class="local-section" id="questions"><h2>Where should I start?</h2><div class="local-grid"><article class="local-card"><h3>Routine care or a new problem?</h3><p>Regular cleaning and a diagnostic repair visit are different scopes. Describe what changed, any error message, and the pool’s current condition.</p>'+link('pool-repair','Explore equipment diagnosis')+'</article><article class="local-card"><h3>Considering a bigger change?</h3><p>Plan known leaks or equipment concerns alongside finish, tile, coping, and control upgrades. Separate essential repair from optional improvements.</p>'+link('pool-remodeling','Plan a pool renovation')+'</article><article class="local-card"><h3>Want local guidance?</h3><p>Find county and neighborhood guides focused on useful pool-care questions, then confirm coverage and appointment availability for your property.</p>'+link('frisco-neighborhoods','Explore Frisco local guides')+'</article></div></section>'+cta()+'</main>'+footer+'<script src="/assets/pool-catalog.js" defer></script></body></html>'
(R/'services/index.html').write_text(s)
print('Rendered 14 service pages and all 21 primary catalogue entries.')
